import{_ as a,H as n,f as p,i as o}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"21 | panic函数、recover函数以及defer语句 （上）","description":"","frontmatter":{},"headers":[{"level":2,"title":"前导知识：运行时恐慌panic","slug":"前导知识-运行时恐慌panic","link":"#前导知识-运行时恐慌panic","children":[]},{"level":2,"title":"问题解析","slug":"问题解析","link":"#问题解析","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Go语言核心36讲/21-panic函数、recover函数以及defer语句（上）.md","filePath":"Go语言核心36讲/21-panic函数、recover函数以及defer语句（上）.md","lastUpdated":1779815739000}'),c={name:"Go语言核心36讲/21-panic函数、recover函数以及defer语句（上）.md"};function i(s,e,r,t,d,l){return n(),p("div",null,[...e[0]||(e[0]=[o(`<h1 id="_21-panic函数、recover函数以及defer语句-上" tabindex="-1">21 | panic函数、recover函数以及defer语句 （上） <a class="header-anchor" href="#_21-panic函数、recover函数以及defer语句-上" aria-label="Permalink to &quot;21 | panic函数、recover函数以及defer语句 （上）&quot;">​</a></h1><p>我在上两篇文章中，详细地讲述了Go语言中的错误处理，并从两个视角为你总结了错误类型、错误值的处理技巧和设计方式。</p><p>在本篇，我要给你展示Go语言的另外一种错误处理方式。不过，严格来说，它处理的不是错误，而是异常，并且是一种在我们意料之外的程序异常。</p><h2 id="前导知识-运行时恐慌panic" tabindex="-1">前导知识：运行时恐慌panic <a class="header-anchor" href="#前导知识-运行时恐慌panic" aria-label="Permalink to &quot;前导知识：运行时恐慌panic&quot;">​</a></h2><p>这种程序异常被叫做panic，我把它翻译为运行时恐慌。其中的“恐慌”二字是由panic直译过来的，而之所以前面又加上了“运行时”三个字，是因为这种异常只会在程序运行的时候被抛出来。</p><p>我们举个具体的例子来看看。</p><p>比如说，一个Go程序里有一个切片，它的长度是5，也就是说该切片中的元素值的索引分别为 <code>0</code>、 <code>1</code>、 <code>2</code>、 <code>3</code>、 <code>4</code>，但是，我在程序里却想通过索引 <code>5</code> 访问其中的元素值，显而易见，这样的访问是不正确的。</p><p>Go程序，确切地说是程序内嵌的Go语言运行时系统，会在执行到这行代码的时候抛出一个“index out of range”的panic，用以提示你索引越界了。</p><p>当然了，这不仅仅是个提示。当panic被抛出之后，如果我们没有在程序里添加任何保护措施的话，程序（或者说代表它的那个进程）就会在打印出panic的详细情况（以下简称panic详情）之后，终止运行。</p><p>现在，就让我们来看一下这样的panic详情中都有什么。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>panic: runtime error: index out of range</span></span>
<span class="line"><span></span></span>
<span class="line"><span>goroutine 1 [running]:</span></span>
<span class="line"><span>main.main()</span></span>
<span class="line"><span> /Users/haolin/GeekTime/Golang_Puzzlers/src/puzzlers/article19/q0/demo47.go:5 +0x3d</span></span>
<span class="line"><span>exit status 2</span></span></code></pre></div><p>这份详情的第一行是“panic: runtime error: index out of range”。其中的“runtime error”的含义是，这是一个 <code>runtime</code> 代码包中抛出的panic。在这个panic中，包含了一个 <code>runtime.Error</code> 接口类型的值。 <code>runtime.Error</code> 接口内嵌了 <code>error</code> 接口，并做了一点点扩展， <code>runtime</code> 包中有不少它的实现类型。</p><p>实际上，此详情中的“panic：”右边的内容，正是这个panic包含的 <code>runtime.Error</code> 类型值的字符串表示形式。</p><p>此外，panic详情中，一般还会包含与它的引发原因有关的goroutine的代码执行信息。正如前述详情中的“goroutine 1 [running]”，它表示有一个ID为 <code>1</code> 的goroutine在此panic被引发的时候正在运行。</p><p>注意，这里的ID其实并不重要，因为它只是Go语言运行时系统内部给予的一个goroutine编号，我们在程序中是无法获取和更改的。</p><p>我们再看下一行，“main.main()”表明了这个goroutine包装的 <code>go</code> 函数就是命令源码文件中的那个 <code>main</code> 函数，也就是说这里的goroutine正是主goroutine。再下面的一行，指出的就是这个goroutine中的哪一行代码在此panic被引发时正在执行。</p><p>这包含了此行代码在其所属的源码文件中的行数，以及这个源码文件的绝对路径。这一行最后的 <code>+0x3d</code> 代表的是：此行代码相对于其所属函数的入口程序计数偏移量。不过，一般情况下它的用处并不大。</p><p>最后，“exit status 2”表明我的这个程序是以退出状态码 <code>2</code> 结束运行的。在大多数操作系统中，只要退出状态码不是 <code>0</code>，都意味着程序运行的非正常结束。在Go语言中，因panic导致程序结束运行的退出状态码一般都会是 <code>2</code>。</p><p>综上所述，我们从上边的这个panic详情可以看出，作为此panic的引发根源的代码处于demo47.go文件中的第5行，同时被包含在 <code>main</code> 包（也就是命令源码文件所在的代码包）的 <code>main</code> 函数中。</p><p>那么，我的第一个问题也随之而来了。我今天的问题是： <strong>从panic被引发到程序终止运行的大致过程是什么？</strong></p><p><strong>这道题的典型回答是这样的。</strong></p><p>我们先说一个大致的过程：某个函数中的某行代码有意或无意地引发了一个panic。这时，初始的panic详情会被建立起来，并且该程序的控制权会立即从此行代码转移至调用其所属函数的那行代码上，也就是调用栈中的上一级。</p><p>这也意味着，此行代码所属函数的执行随即终止。紧接着，控制权并不会在此有片刻的停留，它又会立即转移至再上一级的调用代码处。控制权如此一级一级地沿着调用栈的反方向传播至顶端，也就是我们编写的最外层函数那里。</p><p>这里的最外层函数指的是 <code>go</code> 函数，对于主goroutine来说就是 <code>main</code> 函数。但是控制权也不会停留在那里，而是被Go语言运行时系统收回。</p><p>随后，程序崩溃并终止运行，承载程序这次运行的进程也会随之死亡并消失。与此同时，在这个控制权传播的过程中，panic详情会被逐渐地积累和完善，并会在程序终止之前被打印出来。</p><h2 id="问题解析" tabindex="-1">问题解析 <a class="header-anchor" href="#问题解析" aria-label="Permalink to &quot;问题解析&quot;">​</a></h2><p>panic可能是我们在无意间（或者说一不小心）引发的，如前文所述的索引越界。这类panic是真正的、在我们意料之外的程序异常。不过，除此之外，我们还是可以有意地引发panic。</p><p>Go语言的内建函数 <code>panic</code> 是专门用于引发panic的。 <code>panic</code> 函数使程序开发者可以在程序运行期间报告异常。</p><p>注意，这与从函数返回错误值的意义是完全不同的。当我们的函数返回一个非 <code>nil</code> 的错误值时，函数的调用方有权选择不处理，并且不处理的后果往往是不致命的。</p><p>这里的“不致命”的意思是，不至于使程序无法提供任何功能（也可以说僵死）或者直接崩溃并终止运行（也就是真死）。</p><p>但是，当一个panic发生时，如果我们不施加任何保护措施，那么导致的直接后果就是程序崩溃，就像前面描述的那样，这显然是致命的。</p><p>为了更清楚地展示答案中描述的过程，我编写了demo48.go文件。你可以先查看一下其中的代码，再试着运行它，并体会它打印的内容所代表的含义。</p><p>我在这里再提示一点。panic详情会在控制权传播的过程中，被逐渐地积累和完善，并且，控制权会一级一级地沿着调用栈的反方向传播至顶端。</p><p>因此，在针对某个goroutine的代码执行信息中，调用栈底端的信息会先出现，然后是上一级调用的信息，以此类推，最后才是此调用栈顶端的信息。</p><p>比如， <code>main</code> 函数调用了 <code>caller1</code> 函数，而 <code>caller1</code> 函数又调用了 <code>caller2</code> 函数，那么 <code>caller2</code> 函数中代码的执行信息会先出现，然后是 <code>caller1</code> 函数中代码的执行信息，最后才是 <code>main</code> 函数的信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goroutine 1 [running]:</span></span>
<span class="line"><span>main.caller2()</span></span>
<span class="line"><span> /Users/haolin/GeekTime/Golang_Puzzlers/src/puzzlers/article19/q1/demo48.go:22 +0x91</span></span>
<span class="line"><span>main.caller1()</span></span>
<span class="line"><span> /Users/haolin/GeekTime/Golang_Puzzlers/src/puzzlers/article19/q1/demo48.go:15 +0x66</span></span>
<span class="line"><span>main.main()</span></span>
<span class="line"><span> /Users/haolin/GeekTime/Golang_Puzzlers/src/puzzlers/article19/q1/demo48.go:9 +0x66</span></span>
<span class="line"><span>exit status 2</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E6%A0%B8%E5%BF%8336%E8%AE%B2/images/40359/606ff433a6b58510f215e57792822bd7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E6%A0%B8%E5%BF%8336%E8%AE%B2/images/40359/606ff433a6b58510f215e57792822bd7.png" alt=""></a></p><p>（从panic到程序崩溃）</p><p>好了，到这里，我相信你已经对panic被引发后的程序终止过程有一定的了解了。深入地了解此过程，以及正确地解读panic详情应该是我们的必备技能，这在调试Go程序或者为Go程序排查错误的时候非常重要。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最近的两篇文章，我们是围绕着panic函数、recover函数以及defer语句进行的。今天我主要讲了panic函数。这个函数是专门被用来引发panic的。panic也可以被称为运行时恐慌，它是一种只能在程序运行期间抛出的程序异常。</p><p>Go语言的运行时系统可能会在程序出现严重错误时自动地抛出panic，我们在需要时也可以通过调用 <code>panic</code> 函数引发panic。但不论怎样，如果不加以处理，panic就会导致程序崩溃并终止运行。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>一个函数怎样才能把panic转化为 <code>error</code> 类型值，并将其作为函数的结果值返回给调用方？</p><p><a href="https://github.com/hyper0x/Golang_Puzzlers" target="_blank" rel="noreferrer">戳此查看Go语言专栏文章配套详细代码。</a></p>`,45)])])}const h=a(c,[["render",i]]);export{g as __pageData,h as default};
